/// The scripts that Warp 10 signs and this port refuses (`invalid algorithm`): ISO 9796-2, X9.31 and the
/// PSS without digest, which BouncyCastle has and this port does not.
pub(crate) const DIVERGENT: &[&str] = &[
    r"'hello' 'UTF-8' ->BYTES 'SHA1WITHRSA/ISO9796-2' @PRIV1024 RSASIGN ->HEX",
    r"'hello' 'UTF-8' ->BYTES 'NONEWITHRSAANDMGF1' @PRIV1024 RSASIGN ->HEX",
    r"'hello' 'UTF-8' ->BYTES 'RAWRSASSA-PSS' @PRIV1024 RSASIGN ->HEX",
    r"'hello' 'UTF-8' ->BYTES 'NONEWITHRSASSA-PSS' @PRIV1024 RSASIGN ->HEX",
];

